const $=s=>document.querySelector(s);let session=false;const role=()=>$('#role').value;
function render(){const pending=role()==='pending',canread=session&&!pending,canedit=session&&['editor','admin'].includes(role());$('#sessiontitle').textContent=session?'A demo session is active.':'Welcome to the archive.';$('#sessioncopy').textContent=session?'This is a UI simulation, not an authenticated identity. Tokens and cookies are neither created nor stored.':'In the real application, sign-in happens at Keycloak — not in a password form built here.';$('#login').hidden=session;$('#logout').hidden=!session;$('#state').textContent=session?'SIMULATED / '+role().toUpperCase():'NO DEMO SESSION';$('#locked').hidden=canread;$('#records').hidden=!canread;$('#locked h3').textContent=session&&pending?'Waiting for an explicit role grant.':'Sign-in is required.';$('#locked p').textContent=session&&pending?'The source social-login policy denies access until an admin grant.':'The actual directory and API have no anonymous mode.';$('#start').hidden=session;$('#create').disabled=!canedit;document.querySelectorAll('[data-edit]').forEach(b=>b.disabled=!canedit);$('#locationstatus').textContent=canread?(canedit?'Editor permissions preview: location create/update/delete available in the real service.':'Viewer permissions preview: list and read only.'):'No application records available in this simulated state.'}
function login(){session=true;render();$('#status').textContent='Local session preview started. No Keycloak redirect, password or backend cookie.'}
$('#login').onclick=login;$('#start').onclick=login;$('#role').onchange=render;$('#logout').onclick=()=>{session=false;render();$('#status').textContent='Local state cleared. Real logout is a CSRF-protected POST followed by Keycloak end-session.'};$('#expire').onclick=()=>{session=false;render();$('#status').textContent='Expiry simulated. A real backend session expires after 30 minutes idle and is lost on backend restart.'};
function modal(t,d){$('#dt').textContent=t;$('#dd').textContent=d;$('#dialog').showModal()}
$('#account').onclick=()=>modal('Account handoff to Keycloak','In a real deployment, Keycloak provides password change and linked-account screens, with English and German locales. This English-only static demo does not recreate those credential forms.');
$('#admin').onclick=()=>modal('Admin access stays with the provider','An authorized admin manages users, composite roles, enable/disable, deletion and temporary-password resets in the Keycloak admin console over the tailnet. The public ingress does not expose that console or admin REST API. No user-management form is implemented here.');
$('#create').onclick=()=>modal('Editor capability preview','A real editor can create, update and delete locations. The backend enforces this authorization independently. This demonstration does not save domain records.');
document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>modal('Edit '+b.dataset.edit,'This sample action demonstrates the editor permission boundary. No backend request or location change occurs.'));
$('#test').onclick=()=>{const r=$('#route').value;let text;if(r==='login')text='302 · Start login redirect\nPublic auth entry point.\nPKCE authorization request to Keycloak.';else if(!session)text='401 · Authentication required\nNo server-side session.';else if(r==='me')text='200 · Simulated identity metadata\nusername/name/email/roles/csrfToken in the real response.\nNo real identity or CSRF token is generated here.';else if(role()==='pending')text='403 · Pending role grant\nStricter social-login rule from source.\nImplicit-viewer policy needs reconciliation.';else if(r==='write'&&role()==='viewer')text='403 · Editor role required\nThe backend, not the UI, enforces permission.';else text='200 · Expected authorized access\nRead: viewer/editor/admin.\nWrite: editor/admin.\nNo request was actually sent.';$('#response').textContent=text};
const flow=[['BROWSER → BACKEND','Start with the backend.','GET /api/auth/login/keycloak redirects to the realm authorization endpoint with PKCE. Endpoints are read from configuration, not discovered at startup.'],['KEYCLOAK / AVARC','Identity is established by the provider.','Keycloak renders the password form or brokers Google. Password self-registration, forgot-password and email verification are disabled in the no-email MVP. Brute-force protection is enabled.'],['BACKEND CALLBACK','Exchange the code server-side.','GET /api/auth/callback exchanges the authorization code using the confidential client and file-based secret. Internal Keycloak endpoints handle token/key requests; issuer and browser redirects use the public origin.'],['BROWSER COOKIE / SERVER TOKENS','One origin. One backend session.','Tokens remain in backend memory. The browser has only a host-only HttpOnly session cookie: Secure outside plain-HTTP development, SameSite=Lax. The frontend calls the backend, not Keycloak token endpoints.'],['CSRF-PROTECTED POST','End the session deliberately.','POST /api/auth/logout requires the CSRF token, ends the backend session and redirects through Keycloak end-session to /logged-out. The frontend does not implement its own password or account management.']];
function step(i){const f=flow[i];$('#flowtag').textContent=f[0];$('#flowtitle').textContent=f[1];$('#flowcopy').textContent=f[2];document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('selected',+b.dataset.step===i))}document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>step(+b.dataset.step));render();step(0);
